const listSharedWithMeItems = `-- name: ListSharedWithMeItems :many
SELECT i.id, i.company_id, i.project_id, i.parent_id, i.kind, i.name, i.position, i.created_by,
       i.file_count, i.folder_count, i.video_count, i.total_bytes, i.review_status, i.locked,
       i.created_at, i.updated_at, g.level as grant_level, g.can_download as grant_can_download,
       p.name as project_name, c.name as client_name
FROM items i
JOIN grants g ON g.target_id = i.id AND g.target_type = 'item'
JOIN projects p ON p.id = i.project_id
JOIN clients c ON c.id = p.client_id
WHERE g.company_id = $1 AND g.email = $2 AND i.deleted_at IS NULL
ORDER BY g.updated_at DESC
`

type ListSharedWithMeItemsParams struct {
	CompanyID pgtype.UUID `json:"company_id"`
	Email     string      `json:"email"`
}

type ListSharedWithMeItemsRow struct {
	ID               pgtype.UUID        `json:"id"`
	CompanyID        pgtype.UUID        `json:"company_id"`
	ProjectID        pgtype.UUID        `json:"project_id"`
	ParentID         pgtype.UUID        `json:"parent_id"`
	Kind             string             `json:"kind"`
	Name             string             `json:"name"`
	Position         pgtype.Numeric     `json:"position"`
	CreatedBy        pgtype.UUID        `json:"created_by"`
	FileCount        int32              `json:"file_count"`
	FolderCount      int32              `json:"folder_count"`
	VideoCount       int32              `json:"video_count"`
	TotalBytes       int64              `json:"total_bytes"`
	ReviewStatus     string             `json:"review_status"`
	Locked           bool               `json:"locked"`
	CreatedAt        pgtype.Timestamptz `json:"created_at"`
	UpdatedAt        pgtype.Timestamptz `json:"updated_at"`
	GrantLevel       string             `json:"grant_level"`
	GrantCanDownload bool               `json:"grant_can_download"`
	ProjectName      string             `json:"project_name"`
	ClientName       string             `json:"client_name"`
}

func (q *Queries) ListSharedWithMeItems(ctx context.Context, arg ListSharedWithMeItemsParams) ([]ListSharedWithMeItemsRow, error) {
	rows, err := q.db.Query(ctx, listSharedWithMeItems, arg.CompanyID, arg.Email)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListSharedWithMeItemsRow{}
	for rows.Next() {
		var i ListSharedWithMeItemsRow
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.ProjectID,
			&i.ParentID,
			&i.Kind,
			&i.Name,
			&i.Position,
			&i.CreatedBy,
			&i.FileCount,
			&i.FolderCount,
			&i.VideoCount,
			&i.TotalBytes,
			&i.ReviewStatus,
			&i.Locked,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.GrantLevel,
			&i.GrantCanDownload,
			&i.ProjectName,
			&i.ClientName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

